    std::map<std::string, long> a,b;
    for(long p = 0; p < n; p++){std::string x; std::cin >> x; ++a[x];}
    for(long p = 0; p < n; p++){std::string x; std::cin >> x; ++b[x];}

    long chg(n);
    for(std::map<std::string, long>::iterator it = a.begin(); it != a.end(); it++){
        long u = it->second;
