    std::vector<long> v(n + 1);
    std::vector<long> cnt(n + 1, 0);
    dfs(g, 1, cnt);

    while(q--){
        long u, k; scanf("%ld %ld", &u, &k);
        long res = find(g, cnt, u, k);
        printf("%ld\n", res);
    }

    return 0;
}

#include <cstdio>
