#include <cstdio>
#include <vector>
#include <algorithm>
typedef long long ll;

int main(){

    ll n, m; scanf("%lld %lld", &n, &m);
    ll sa(0), td(0);
    std::vector<ll> d(n);
    for(ll p = 0; p < n; p++){
        ll a, b; scanf("%lld %lld", &a, &b);
        sa += a; td += (a - b); d[p] = a - b;
    }
    
    if(sa <= m){puts("0"); return 0;}
    else if(m < sa - td){puts("-1"); return 0;}
    else{
        sort(d.rbegin(), d.rend());
        ll cnt(0);
        for(ll p = 0; p < n; p++){
            sa -= d[p];
            if(sa <= m){cnt = p + 1; break;}
        }

        printf("%lld\n", cnt);
    }

    return 0;
}

#include <cstdio>
typedef long long ll;

int main(){
    ll n, k, s; scanf("%lld %lld %lld", &n, &k, &s);

    if((s < k) || ((n - 1) * k < s)){puts("NO"); return 0;}

    puts("YES");

    ll step = 1;
    while(k--){
        ll rm = (s - k < n - 1) ? (s - k) : (n - 1);
        s -= rm;
        if(step + rm <= n){step += rm;}
        else{step -= rm;}
        printf("%lld ", step);

    }
    puts("");

    return 0;
}

