std::vector<std::vector<int> > edges;
std::vector<bool> visited;
int totalVisited(0);

void dfs(int node){
    if(visited[node]){return;}
    visited[node] = 1; ++totalVisited;
    for(int p = 0; p < edges[node].size(); p++){dfs(edges[node][p]);}
}


