void dfs(long node, long from, const std::vector<std::vector<long> > &g, std::vector<long> &v){
    if(v[node]){return;}
    v[node] = 3 - v[from];
    for(long p = 0; p < g[node].size(); p++){
        long next = g[node][p];
        if(v[next]){continue;}
        dfs(next, node, g, v);
    }
    
    return;
}

