std::vector<bool> getBinaryVector(long x){
    std::vector<bool> v;
    while(x > 0){v.push_back(x % 2); x /= 2;}
    return v;
}

int countOnes(std::vector<bool> v){
    int cnt(0);
    for(int p = 0; p < v.size(); p++){cnt += v[p];}
    return cnt;
}

int main(){

