#include <iostream>

std::string stringsum(std::string a, std::string b){

    std::string res("");
    int carry(0);
    for(long p = 0; p < a.size() || p < b.size() || carry; p++){
        long x = p < a.size() ? a[a.size() - 1 - p] : '0';
        long y = p < b.size() ? b[b.size() - 1 - p] : '0';
        long z = carry + x + y - 2 * '0';
        if(z > 9){carry = 1; z -= 10;}
        else{carry = 0;}
        char digit = '0' + z;
        res = digit + res;
    }

    return res;
}

