        for(long r = 1; r < rd; r++){
            long x, y; scanf("%ld %ld", &x, &y);
            --x; --y;
            g[y].push_back(x);
            g[x].push_back(y); 
        }
        
        total += getDiameter(g);
    }

    printf("%ld\n", total);

