bool check(const std::vector<ll> v, ll num, ll x, ll a, ll y, ll b, ll lcm, ll k){

    ll both = num / lcm;
    ll fc = (num / a) - both;
    ll sc = (num / b) - both;

    ll total(0);
    for(ll p = 0; p < num; p++){
        if(both > 0){total += (v[p] * (x + y) / 100); --both;}
        else if(fc > 0){total += v[p] * x / 100; --fc;}
        else if(sc > 0){total += v[p] * y / 100; --sc;}
    }

    return (total >= k);
}

