        for(ll p = 0; p < b.size(); p++){
            b[p] += carry; carry = 0;
            if(b[p] <= 1){continue;}
            for(ll u = 0; u <= p; u++){b[u] = 0;}
            carry = 1;
        }
        if(carry){b.push_back(1);}
        ll m(0); for(ll p = 0, cur = 1; p < b.size(); p++, cur *= 3){m += b[p] * cur;}
        printf("%lld\n", m);
    }

    return 0;
}

