ll phi(ll x){

    ll cnt(x);
    for(ll p = 2; p * p <= x; p++){
        if(x % p){continue;}
        ll mult(0);
        while(x % p == 0){x /= p; ++mult;}
        cnt -= (cnt / p);
    }

    if(x > 1){cnt -= (cnt / x);}
    return cnt;
}


