                for(long p = 0; p < 2; p++) {
                    long tstC = tstB * (c / tstB) + p * tstB;
                    long tstcnt = std::abs(tstA - a) + std::abs(tstB - b) + std::abs(tstC - c);
                    if(tstcnt < cnt){cnt = tstcnt; A = tstA; B = tstB; C = tstC;}
                }
            }
        } 

        printf("%ld\n%ld %ld %ld\n", cnt, A, B, C);
    }

}

