typedef long long ll;

ll dfs(ll node, ll from, const std::vector<std::vector<ll> > &g, ll depth, std::vector<ll> &sv){
    const std::vector<ll> v = g[node];
    ll sz(1);
    for(ll p = 0; p < v.size(); p++){
        if(v[p] == from){continue;}
        sz += dfs(v[p], node, g, depth + 1, sv);
    }

    sv[node] = sz - depth;
    return sz;
}


