            else{f.back() *= y;}
            while(x % y == 0){x /= y;}
        }

        if(x > 1){
            if(f.size() < 2){f.push_back(x);}
            else{f.back() *= x;}
        }

        if(f.size() > 1){a[p] = f[0]; b[p] = f[1];}
