            g[x].erase(y); g[y].erase(x);
            if(g[y].size() == 1){q.push(y);}
        }

        ll ans(0);
        for(ll p = 1; p <= n; p++){ans += dep[p] * (dep[p] - 1) / 2 + dep[p] * (n - dep[p]);}
        printf("%lld\n", ans);
    }

}

