        if(!possible){puts("-1"); continue;}
        if(!poscnt || !negcnt){puts("0"); continue;}

        long c = posdiff;
        long m = posdiff - negdiff;

        if(a[0] >= m){possible = false;}
        for(long p = 1; possible && p < n; p++){
            long x = (a[p - 1] + c) % m;
            if(x != a[p]){possible = false;}
        }

        if(possible){printf("%ld %ld\n", m, c);}
        else{puts("-1");}
    }

