void f(long start, long end, long curDepth, const std::vector<long> &dv, std::vector<long> &depth){

    if(start >= end){return;}
    long idx(start);
    for(long p = start + 1; p < end; p++){
        if(dv[p] > dv[idx]){idx = p;}
    }

    depth[idx] = curDepth;
    f(start, idx, curDepth + 1, dv, depth);
    f(idx + 1, end, curDepth + 1, dv, depth);
}

