        for(long p = 0; p < m; p++) {
            long val(v[p]); bool done(0);
            for(long row = 0; !done && row < n; row++) {
                for(long col = 0; !done && col < m; col++) {
                    if(a[row][col] != val){continue;}
                    grid[p][row] = val;
