using namespace std;

int main(){
    int numStudents, numCourses; scanf("%d %d\n", &numStudents, &numCourses);
    int maxGrade = 0; char temp;
    bool *successful = new bool[numStudents];
    int *grades = new int[numStudents * numCourses];

    for(int n = 0; n < numStudents; n++){
        for(int m = 0; m < numCourses; m++){scanf("%c", &temp); grades[n * numCourses+ m] = temp - '0';}
        scanf("\n");
    }

    for(int n = 0; n < numStudents; n++){successful[n] = 0;}

    for(int m = 0; m < numCourses; m++){
        maxGrade = 0;
        for(int n = 0; n < numStudents; n++){maxGrade = max(maxGrade, grades[n * numCourses + m]);}
        for(int n = 0; n < numStudents; n++){if(grades[n * numCourses + m] == maxGrade){successful[n] = 1;}}
    }

    int total = 0;
    for(int student = 0; student < numStudents; student++){total += successful[student];}
    printf("%d\n", total);
    return 0;
}

#include <cstdio>

int main(){

    const long maxSteps = 1000000000;

    long long yardX(0), yardY(0); scanf("%lld %lld", &yardX, &yardY);
    long long currentX(0), currentY(0); scanf("%lld %lld", &currentX, &currentY);

    long long total(0);
    long numVectors(0); scanf("%ld", &numVectors);

    while(numVectors--){

        long vectorX(0), vectorY(0); scanf("%ld %ld", &vectorX, &vectorY);

        long numStepsX(maxSteps); 
        if(vectorX > 0){numStepsX = (yardX - currentX) / vectorX;} 
        else if(vectorX < 0){numStepsX = (currentX - 1) / (-vectorX);}

        long numStepsY(maxSteps); 
        if(vectorY > 0){numStepsY = (yardY - currentY) / vectorY;} 
        else if(vectorY < 0){numStepsY = (currentY - 1) / (-vectorY);}

        long numSteps(0);
        if(numStepsX > 0 && numStepsY > 0){numSteps = (numStepsX < numStepsY) ? numStepsX : numStepsY;}

        currentX += numSteps * vectorX;
        currentY += numSteps * vectorY; 
        total += numSteps;
        
    }

    printf("%lld\n", total);

    return 0;
}

