#include <cstdio>
#include <vector>
#include <algorithm>
typedef long long ll;

ll f(std::vector<ll> &v, ll s){

    ll left(0), right(v.size() - 1);
    ll res(0);
    while(left < right){
        if(v[left] + v[right] > s){--right;}
        else{res += right - left; ++left;}
    }

    return res;
}

