int getDist(const std::string &target, const std::string &s){

    int a(0), b(0), cnt(0);
    while(a < target.size() || b < s.size()){
        if(a >= target.size()){++b; ++cnt;}
        else if(b >= s.size()){++a; ++cnt;}
        else if(target[a] == s[b]){++a; ++b;}
        else{++b; ++cnt;}
    }

    return cnt;
}

