        long idx(-1); bool check = isPrime(sum);
        if(check){for(long p = 0; p < n; p++){if(!isPrime(sum - a[p])){idx = p; break;}}}

        printf("%ld\n", n - check);
        for(long p = 0; p < n; p++){
            if(p == idx){continue;}
            printf("%ld ", p + 1);
        }
        puts("");
    }

}

