using namespace std;

class directory{
private:
    vector<string> path;
public:
    void pwd(){
        cout << "/";
        for(int k = 0; k < path.size(); k++){cout << path[k] << "/";}
        cout << endl;
    }

    void pop(){path.pop_back();}
    void add(string newDir){
        if(newDir == ".."){path.pop_back();}
        else{path.push_back(newDir);}
    }
    void root(){path.clear();}
};


int main(){
    int numCommands; scanf("%d\n", &numCommands);
    directory dir;
    string command;
    while(numCommands--){
        getline(cin, command);
        if(command == "pwd"){dir.pwd();}
        else if (command[0] == 'c' && command[1] == 'd'){
            char c; int index = 3; string newFolder = "";
            if(command[index] == '/'){index++; dir.root();}
            while(index < command.size()){
                c = command[index++];
                if(c != '/'){newFolder += c;}
                else{dir.add(newFolder);newFolder = "";}
            }
            if(newFolder != ""){dir.add(newFolder);}
        }
    }
    
    return 0;
}

#include <cstdio>

int main(){
    int n; scanf("%d", &n);
    long *value = new long[n];
    for(int k = 0; k < n; k++){scanf("%ld", value + k);}

    long output = 0, currentMax = - 30000000;
    for(int div = 1; div <= n / 3 ; div++){ // Minimum allowed triangle; If one or two vertices allowed, upper bound should be equal to n
        if(n % div != 0){continue;}
        for(int rem = 0; rem < div; rem++){
            output = 0;
            for(int k = 0; k < n / div; k++){output += value[div * k + rem];}
            if(output > currentMax){currentMax = output;}
        }
    }

    printf("%ld\n", currentMax);
    return 0;
}

