#include <cstdio>
#include <vector>
#include <map>


int main(){

    const int D = 5;
    long t; scanf("%ld", &t);
    while(t--){

        long n; scanf("%ld", &n);
        std::map<std::pair<long, long>, long> first, second, both, neither;
        for(long row = 0; row < n; row++){
            std::vector<int> f(D, 0);
            for(long p = 0; p < D; p++){scanf("%d", &f[p]);}
            for(long u = 0; u < D; u++){
                for(long v = u + 1; v < D; v++){
                    std::pair<long, long> combo = std::make_pair(u, v);
                    if(f[u] && f[v]){++both[combo];}
                    else if(f[u]){++first[combo];}
                    else if(f[v]){++second[combo];}
                    else{++neither[combo];}
                }
            }
        }

        bool possible(false);
        for(long u = 0;!possible &&  u < D; u++){
            for(long v = u + 1; !possible && v < D; v++){
                std::pair<long, long> combo = std::make_pair(u, v);
                if(neither[combo] > 0){continue;}
                if(first[combo] + both[combo] >= n / 2 && second[combo] + both[combo] >= n / 2){possible = true; break;}
            }
        }

        puts(possible ? "YES" : "NO");
    }

}

#include <cstdio>
#include <map>
typedef long long ll;


int main(){

    ll t; scanf("%lld", &t);
    while(t--){

        ll n; scanf("%lld", &n);
        std::map<ll, ll> cnt; ll sum(0);
        for(ll p = 0; p < n; p++){
            ll x; scanf("%lld", &x);
            ++cnt[x];
            sum += x;
        }

        ll check = 2 * sum / n;
        bool possible = (n * check == 2 * sum);
        ll res(0);

        if(!possible){puts("0"); continue;}
        for(std::map<ll, ll>::iterator it = cnt.begin(); it != cnt.end(); it++){
            ll key = it->first;
            if(2 * key > check){continue;}
            ll left = it->second;
            ll right = cnt.count(check - key) ? cnt[check - key] : 0;
            res += (2 * key == check) ? (left * (left - 1) / 2) : (left * right);
        }

        printf("%lld\n", res);

    }

}

#include <cstdio>
