typedef long long ll;

bool check(ll lines, ll k, ll x){
    ll total;
    if(lines <= k){total = lines * (lines + 1) / 2;}
    else{total = k * k - (2 * k - 1 - lines) * (2 * k - lines) / 2;}
    return total < x;
}

