typedef long long ll;


bool check(const std::vector<ll> &a, const ll &h, const ll &k){

    ll sum(0), cur(0); 
    for(ll p = 0; p < a.size(); p++){
        ll tst = a[p] + k - cur;
        sum += (tst < k) ? tst : k;
        cur = a[p] + k;
    }

    return (sum >= h);
}


