struct penstool{long order, price, kind;};
bool compenstool(penstool A, penstool B){
    if(A.kind == B.kind){return A.price > B.price;}
    else if(A.kind == 1){return 1;}
    else if(B.kind == 1){return 0;}
    return 0;
}

int main(){

