    for(int p = 1; p <= n; p++){
        itemVec[p].order = p;
        scanf("%ld %ld\n", &itemVec[p].price, &itemVec[p].kind);
        if(itemVec[p].price < minPrice){minPrice = itemVec[p].price;}
    }

    sort(++itemVec.begin(), itemVec.end(), compenstool);

    double totalPrice = 0;
    for(long p = 1; p <= n; p++){
        if(itemVec[p].kind == 1 && p < k){totalPrice += 0.5 * itemVec[p].price;}
        else{totalPrice += itemVec[p].price;}
    }
    if(itemVec[k].kind == 1){totalPrice -= 0.5 * minPrice;}

    printf("%.1lf\n", totalPrice);
    for(long p = 1; p < k; p++){printf("1 %ld\n", itemVec[p].order);}
    printf("%ld ", n - k + 1); for(long p = k; p <= n; p++){printf("%ld ", itemVec[p].order);}
    puts("");

    return 0;
}

#include <cstdio>
#include <vector>

std::vector<std::vector<long long> > count;
std::vector<std::vector<long long> > edges;
long long n, k, output;

void dfs(long long node, long long from){

    count[node][0] = 1;
    for(long long p = 0; p < edges[node].size(); p++){
        long long v = edges[node][p];
        if(v == from){continue;}
        dfs(v , node);
        for(long long d = 1; d <= k; d++){output += count[node][d - 1] * count[v][k - d];}
        for(long long d = 1; d <= k; d++){count[node][d] += count[v][d - 1];}
    }
}



