long convertToLong(std::string x){

    if(x[0] == '0' && x.size() > 1){return -1;}
    if(x.size() > 7){return -1;}

    long output(0);
    for(size_t k = 0; k < x.size(); k++){output = 10 * output + (x[k] - '0');}

    if(output > 1000000){return -1;}
    return output;
}

