typedef long long ll;

ll dist(const std::pair<ll, ll> &r, const std::pair<ll, ll> &s){
    ll dx = r.first - s.first; if(dx < 0){dx = -dx;}
    ll dy = r.second - s.second; if(dy < 0){dy = -dy;}
    return dx + dy;
}

