struct strat{long order; double outcome;};

bool stratSort(strat A, strat B){
    if(A.outcome < B.outcome){return 0;}
    else if(A.outcome == B.outcome){return A.order < B.order;}
    return 1;
};


int main(){

    long n, t1, t2, k; scanf("%ld %ld %ld %ld\n", &n, &t1, &t2, &k);
