            if(sb == sa){valid = false;}
            if(sa > sb && last != 'A'){valid = false;}
            if(sb > sa && last != 'B'){valid = false;}

            if(valid){
                if(sa > sb){a = true;}
                else{b = true;}
            }
        }

        char res('?');
        if(a && !b){res = 'A';}
        else if(!a && b){res = 'B';}
        std::cout << res << std::endl;
    }

}

