        long m; scanf("%ld", &m);
        while(m--){
            long from, to; scanf("%ld %ld", &from, &to);
            --from; --to;
            long res(0);
            if(from < to){res = f[to - 1] - (from ? f[from - 1] : 0);}
            else{res = g[to + 1] - ((from + 1 < n) ? g[from + 1] : 0);}
            printf("%ld\n", res);
        }

    }

}

