        long diff = (b - a);
        diff = (diff < minus ? diff : minus);
        b     -= diff;
        minus -= diff;

        diff = (b - a);
        diff = (diff < plus ? diff : plus);
        a     += diff;
        plus -= diff;

        if(minus && plus){
            long mn = (minus < plus ? minus : plus);
            minus -= mn; plus -= mn;
        }

        if(minus){a -= (minus + 1) / 2;}
        else if(plus){a += plus / 2;}
        printf("%ld\n", a);
    }

}

