        long xt(0), yt(0);
        for(long p = 0; p < s.size(); p++){
            if(s[p] == 'N'){++yt;}
            else if(s[p] == 'S'){--yt;}
            else if(s[p] == 'E'){++xt;}
            else if(s[p] == 'W'){--xt;}
        }

        long x(0), y(0);
        bool ans(check(0, 0, a, b, xt, yt));
        for(long p = 0; p < s.size() && !ans; p++){
            if(s[p] == 'N'){++y;}
            else if(s[p] == 'S'){--y;}
            else if(s[p] == 'E'){++x;}
            else if(s[p] == 'W'){--x;}
            if(check(x, y, a, b, xt, yt)){ans = true;}
        }

        std::cout << (ans ? "YES" : "NO") << std::endl;
    }

}

