void dfs(long node, long from, const std::vector<std::vector<long> > &g, std::vector<long> &dist){
    for(long nxt : g[node]){
        if(nxt == from){continue;}
        dist[nxt] = dist[node] + 1;
        dfs(nxt, node, g, dist);
    }
}


