void dfs(long node, const std::vector<std::vector<long> > &g, std::vector<long> &path, std::vector<bool> &been){

    if(been[node]){return;} //Should never need to exit here
    been[node] = 1;
    path.push_back(node);
    std::vector<long> adj = g[node];
    bool more(false);
    for(long p = 0; p < adj.size(); p++){
        long nn = adj[p];
        if(been[nn]){continue;}
        more = false;
        dfs(nn, g, path, been);
        break;
    }

    return;
}


