void dfs(const std::vector<std::vector<long> > &g, long u, std::vector<bool> &been, long dist, double &total){

    if(been[u]){return;}
    been[u] = true;
    total += 1.0 / (1 + dist);
    for(long p = 0; p < g[u].size(); p++){
        long v = g[u][p];
        if(been[v]){continue;}
        dfs(g, v, been, 1 + dist, total);
    }

    return;
}


