    long c(0), t(0), q(0), maxSize(0),previousTime(0), lastTime(0), finalTime(0);
    while(n--){
        scanf("%ld %ld", &t, &c);
        if(t < lastTime){q += c - (t - previousTime); lastTime += c;}
        else{q = c; lastTime = t + c;}
        if(q > maxSize){maxSize = q;}
