        for(long x = 1; x < 2 * N - 1; x++){
            for(long y = 1; y < 2 * N - 1; y++){
                if(a[x][y] < F){continue;}
                done = false;
                a[x+1][y] += a[x][y] / F;
                a[x-1][y] += a[x][y] / F;
                a[x][y+1] += a[x][y] / F;
                a[x][y-1] += a[x][y] / F;
                a[x][y] %= F;
            }
        }
    }

    while(t--){
        long x, y; scanf("%ld %ld",&x, &y);
        if(x < -N || x >= N || y < -N || y >= N){puts("0");}
        else{printf("%ld\n", a[N+x][N+y]);}
    }

    return 0;
}

