bool dfs(long rem, long cs, const std::vector<bool> &w, std::vector<long> &res){

    if(rem <= 0){return true;}
    long sa = (cs < 0) ? -1 : 1;
    for(long p = 1; p <= w.size(); p++){
        if(!w[p]){continue;}
        if(res.size() > 0 && res.back() == p){continue;}
        long csn = cs - sa * p;
        long sb = (csn < 0) ? -1 : 1;
        if(csn == 0 || sa * sb >= 0){continue;}
        res.push_back(p);
        bool u = dfs(rem - 1, csn, w, res);
        if(u){return true;}
        else{res.pop_back();}
    }

    return false;
}


