            paint %= currentDiff;
            remDigit--;
        }

        
        for(int digit = N - 1; digit >= minDigit; digit--){
            for(int m = 0; m < occurence[digit]; m++){
                printf("%d", digit);
            }
        }
        puts("");
    }

    else{puts("-1");}

