bool firstWins(long n, long m, long k){

    long min = (m < n) ? m : n;
    if(min % (k + 1) == 0){return true;}
    else if(k == 1 || (min / (k + 1)) % 2 == 0){return (m % 2) != (n % 2);}
    else{return (m % 2) == (n % 2);}
}

