    bool started(0), done(0), possible(1);
    long start(1), end(1);

    for(int p = 1; p < n; p++){
        if(data[p - 1] > data[p] && !started){started = 1; start = p;}
        if(data[p - 1] < data[p] && started && !done){done = 1; end = p;}
