    if((start > 1 && data[start - 2] > data[end - 1]) || (end < n && data[start - 1] > data[end])){possible = 0;}

    if(!possible){puts("no");}
    else{puts("yes"); printf("%ld %ld\n", start, end);}


    return 0;
}

