int digitSum(long input){

    int output(0);
    while(input > 0){
        output += (input % 10);
        input /= 10;
    }

    return output;
}

long long myPower(long base, long exponent){
    long long output(1);
    for(int p = 0; p < exponent; p++){output *= base;}
    return output;
}

