bool check(long h, const std::vector<long> &a, long m, long w){

    const long n = a.size();
    std::vector<long> v(n + w + 1, 0);
    long cnt(0), total(0);
    for(long p = 0; p < n; p++){
        cnt += v[p];
        long diff = h - (a[p] + cnt);
        if(diff < 0){continue;}
        cnt += diff;
        total += diff; if(total > m){return false;}
        v[p + w] = -diff;
    }

    return true;
}


