        changing.push_back(std::pair<int,int>(a,b));
    }


    bool done;
    int output(0);

    for(int k = l; k <= r; k++){
        done = 0;
        for(int x = 0; x < fixed.size(); x++){
            if(done){continue;}
            for(int y = 0; y < changing.size(); y++){
                if((fixed[x].second < k + changing[y].first) || (k + changing[y].second < fixed[x].first)){continue;}
                else{done = 1; ++output; break;}
            }
        }
    }

    printf("%d\n", output);

    return 0;
}

