void dfs(int x){

    if(visited[x]){return;}
    visited[x] = 1; inpath[x] = 1;
    for(int p = 0; p < previous[x].size(); p++){
        int current = previous[x][p];
        if(inpath[current]){puts("Impossible"); exit(0);}
        else if(!visited[current]){dfs(current);}
    }
    inpath[x] = 0;
    sequence.push_back('a' + x);
