#include <iostream>
#include <map>

int main(){

    long yay(0), whoops(0);

    std::map<char, long> countMsg;
    std::string msg; getline(std::cin, msg);
    for(int p = 0; p < msg.size(); p++){
        if(countMsg.count(msg[p]) > 0){++countMsg[msg[p]];}
        else{countMsg.insert(std::pair<char, int>(msg[p], 1));}
    }

    std::map<char, long> countNews;
    std::string news; getline(std::cin, news);
    for(int p = 0; p < news.size(); p++){
        char letter = news[p];
        if(countMsg.count(letter) && countMsg[letter] > 0){++yay; --countMsg[letter]; continue;}
        if(countNews.count(letter) > 0){++countNews[letter];}
        else{countNews.insert(std::pair<char, int>(letter, 1));}
    }

    for(char letter = 'a'; letter <= 'z'; letter++){
        char capLetter = letter + 'A' - 'a';

        long msgCount(0);
        if(countMsg.count(letter) > 0){msgCount += countMsg[letter];}
        if(countMsg.count(capLetter) > 0){msgCount += countMsg[capLetter];}

        long newsCount(0); 
        if(countNews.count(letter) > 0){newsCount += countNews[letter];}
        if(countNews.count(capLetter) > 0){newsCount += countNews[capLetter];}

        if(msgCount <= newsCount){whoops += msgCount;}
        else{whoops += newsCount;}
    }

    std::cout << yay << " " << whoops << std::endl;

    return 0;
}

#include <cstdio>
#include <vector>

int main(){

    long long n, m, k; scanf("%lld %lld %lld\n", &n, &m, &k);
    std::vector<long long> app(n), pos(n);
    for(long long p = 0; p < n; p++){long long temp; scanf("%lld", &temp); app[p] = temp - 1; pos[temp - 1] = p;}

    long long count(0);
    while(m--){
        long long currentApp; scanf("%lld\n", &currentApp); --currentApp;
        long long currentPos = pos[currentApp];
        count += (1 + (currentPos / k));
        if(currentPos == 0){continue;}

        long long previousApp = app[currentPos - 1];
        app[currentPos - 1] = currentApp; app[currentPos] = previousApp;
        --pos[currentApp]; ++pos[previousApp];
    }

    printf("%lld\n", count);


    return 0;
}

#include <cstdio>
#include <vector>

int main(){

    int n; double p; int t;
    scanf("%d %lf %d\n", &n, &p, &t);

    std::vector<std::vector<double> > prob(t + 1, std::vector<double>(n + 1, 0));

    double probNone(1);
    for(int time = 0; time <= t; time++){prob[time][0] = probNone; probNone *= (1 - p);}

    for(int time = 1; time <= t; time++){
        for(int num = 1; num <= n && num <= t; num++){
            prob[time][num] = p * prob[time - 1][num - 1] + (num == n ? 1 : (1 - p)) * prob[time - 1][num];
        }
    }

    double ans(0);
    for(int k = 0; k <= n; k++){ans += prob[t][k] * k;}
    printf("%.8lf\n", ans);

    return 0;
}

