    while(a.back() == 0){a.pop_back();}
    int64_t left(a.size()), right(1e16), time(1e16);
    while(left <= right){
        int64_t cand = (left + right) / 2;
        if(check(a, m, cand)){time = cand; right = cand - 1;}
        else{left = cand + 1;}
    }

    printf("%lld\n", time);

    return 0;
}

