    else{std::cout << "-" << std::endl;}

    if(nonint.size() > 0){
        std::cout<< "\"";
        for(size_t p = 0; p < nonint.size() - 1; p++){std::cout << nonint[p] << ",";}
        std::cout << nonint.back() << "\"" << std::endl;
    }
    else{std::cout << "-" << std::endl;}

    return 0;
}

