#include <iostream>
#include <string>

std::string convert(std::string s){
    std::string output("");
    for(int p = 0; p < s.size(); p++){
        if('a' <= s[p] && s[p] <= 'z'){output += s[p];}
        else if('A' <= s[p] && s[p] <= 'Z'){output += (s[p] - 'A' + 'a');}
    }
    return output;
}



int main(){

