int main(){

    ll n; scanf("%lld", &n);
    std::vector<ll> start(n + 1, 0), finish(n + 1, 0);
    for(ll p = 1; p <= n; p++){
        ll s, d; scanf("%lld %lld", &s, &d);
        ll a(s), b(s + d - 1);
        bool free(true);
        for(ll u = 0; u < p; u++){if(!((b < start[u]) || (finish[u] < a))){free = false; break;}}
        if(free){start[p] = s; finish[p] = b; continue;}

        for(ll t = 0; t < p; t++){
            a = finish[t] + 1;
            b = a + d - 1;
            free = true;
            for(ll u = 0; u < p; u++){if(!((b < start[u]) || (finish[u] < a))){free = false; break;}}
            if(!free){continue;}
            else if((start[p] == 0) || (a < start[p])){start[p] = a; finish[p] = b;}
        }
    }

    for(ll p = 1; p <= n; p++){printf("%lld %lld\n", start[p], finish[p]);}

    return 0;
}

#include <iostream>
#include <vector>
#include <set>


bool checkPattern(std::string test, std::string pat){
    if(test.size() != pat.size()){return false;}
    for(int p = 0; p < pat.size(); p++){
        if(pat[p] == '?'){continue;}
        if(pat[p] != test[p]){return false;}
    }

    return true;
}


std::string updatePattern(std::string s, std::string pattern){
    if(pattern.size() == 0){return s;}
    if(pattern.size() != s.size()){return "";}
    for(int p = 0; p < pattern.size(); p++){if(pattern[p] != '?' && pattern[p] != s[p]){pattern[p] = '?';}}
    return pattern;
}


int main(){

    std::ios_base::sync_with_stdio(false);
    int n, m; std::cin >> n >> m;
    std::vector<std::string> v(n + 1);
    for(int p = 1; p <= n; p++){std::cin >> v[p];}

