    for(long p = 1; p <= m; p++){scanf("%ld", &a[p]);}

    bool possible(false);
    long left(0), right(n - 1);
    while(left <= right){
        long mid = (left + right) / 2;
        if(check(d, a, m, mid)){right = mid - 1; possible = true;}
        else{left = mid + 1;}
    }

    printf("%ld\n", possible ? (left + 1) : (-1));

    return 0;
}

