        ++count;
        if(v.size() == 1){continue;}
        long mx(-1), mxp(-1);
        for(long p = 0; p < v.size(); p++){
            if(v[p] > mx){
                if(p > 0 && v[p - 1] < v[p]){mx = v[p]; mxp = p;}
                if(p + 1 < v.size() && v[p] > v[p + 1]){mx = v[p]; mxp = p;}
            }
        }

