        long mxpR(mxp);
        if(mxp > 0 && v[mxp - 1] <= v[mxp]){mxpR = mxp + 1; f.push_back(std::make_pair(mxp + (count - 1), 'R'));}

        for(long p = 0; p < v.size(); p++){
