void dfs(const std::vector<std::vector<long>> &g, long node, std::vector<bool> &vis, long &order, long &dsz){

    if(vis[node]){return;}
    vis[node] = true;
    ++order; dsz += g[node].size();
    for(long p = 0; p < g[node].size(); p++){
        long nn = g[node][p];
        if(vis[nn]){continue;}
        dfs(g, nn, vis, order, dsz);
    }

    return;
}


