char ans[333][555];

void prt(int h, int d, int f, int c) {
    int r = h;
    for(int p=0;p<d;p++)
        ans[r-p][c] = ans[r+p][c] = '|';
    ans[r-d][c] = ans[r+d][c] = '+';
    ans[r-d][c+f] = ans[r+d][c+f] = '-';
}

