struct point{double x,y;};

double dist(point p1,point p2,point p3){
    double a = p3.y - p1.y;
    double b = p1.x - p3.x;
    double c = -b * p3.y - p3.x * a;
    double r = (a * p2.x + b * p2.y + c) / sqrt(a*a + b*b);
    r = (r > 0) ? r : -r;
    return r;
}


