int64_t countSums(const std::vector<int64_t> &cs, int64_t target){

    int64_t count(0);
    std::map<int64_t, int64_t> m;
    for(long p = cs.size() - 1; p >= 0; p--){
        int64_t seek = cs[p] + target;
        if(m.count(seek) > 0){count += m[seek];}
        if(m.count(cs[p]) <= 0){m[cs[p]] = 0;}
        ++m[cs[p]];
    }

    return count;
}


