double getTime(const std::vector<double> &x, const std::vector<double> &v, double probe){

    double maxTime(0);
    for(long p = 0; p < x.size(); p++){
        double time = (probe - x[p]) / v[p];
        if(time < 0){time = -time;}
        maxTime = (maxTime > time) ? maxTime : time;
    }

    return maxTime;
}



