typedef long long ll;

ll extendedGcd(ll a, ll b, ll &x, ll &y) {
    if(!b){x = 1; y = 0; return a;}
    ll g = extendedGcd(b, a % b, x, y);
    ll t = x; x = y; y = t - (a / b) * y;
    return g;
}


