#include <cstdio>
#include <vector>

void dfs(long node, const std::vector<std::vector<long> > &g, std::vector<bool> &been, std::vector<long> &dist){

    if(been[node]){return;}
    been[node] = 1;
    for(long p = 0; p < g[node].size(); p++){
        long u = g[node][p];
        if(been[u]){continue;}
        dist[u] = dist[node] + 1;
        dfs(u, g, been, dist);
    }

    return;
}


int main(){

