    for(long p = 0; p < m; p++){
        long x, y; scanf("%ld %ld", &x, &y);
        --x; --y;
        g[x].push_back(y); g[y].push_back(x);
    }

    ll totalCost(0);
    std::vector<bool> visited(n, false);

    for(long p = 0; p < n; p++){
        if(visited[p]){continue;}
        long compCost(costVec[p]);
        dfs(p, compCost, visited, costVec, g);
        totalCost += compCost;
    }

    printf("%lld\n", totalCost);
    
    return 0;
}

