ll qexp(ll base, ll x, ll MOD){

    if(x == 0){return 1;}
    base %= MOD;
    ll r = qexp(base, x / 2, MOD);
    ll res = (((r * r) % MOD) * ((x & 1) ? (base % MOD) : 1)) % MOD;
    return res;
}

