double getDist(double x1, double y1, double x2, double y2){
    return sqrt((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1));
}

int main(){

    double R, x1, y1, x2, y2; scanf("%lf %lf %lf %lf %lf", &R, &x1, &y1, &x2, &y2);
