#include <cstdio>
#include <vector>

long dfs(const std::vector<std::vector<long> > &g, long node, long from, long &cnt){

    long below(1);
    for(long p = 0; p < g[node].size(); p++){
        long cur = g[node][p];
        if(cur == from){continue;}
        long u = dfs(g, cur, node, cnt);
        if(u % 2 == 0){++cnt;}
        below += u;
    }

    return below;
}

