typedef long long ll;

ll find(const std::vector<ll> &L, ll x){
    if(x == L[x]){return x;}
    return find(L, L[x]);
}

void merge(std::vector<ll> &L, std::vector<ll> &g, std::vector<ll> &s, ll x, ll y){
    ll u = find(L, x);
    ll v = find(L, y);
    if(u == v){return;}
    if(g[u] < g[v]){
        L[u] = v; 
        g[v] += g[u];
        s[u] -= s[v];
    }
    else{
        L[v] = u;
        g[u] += g[v];
        s[v] -= s[u];
    }
}

ll get(const std::vector<ll> &L, std::vector<ll> &s, ll x){
    if(x == L[x]){return s[x];}
    return (s[x] + get(L, s, L[x]));
}

