    while(m--){
        std::string action; std::cin >> action;
        if(action == "add"){
            ll player, val; std::cin >> player >> val;
            ll leader = find(L, player);
            s[leader] += val;
        }
        else if(action == "join"){
            ll a, b; std::cin >> a >> b;
            a = find(L, a); b = find(L, b);
            if(a == b){continue;}
            merge(L, g, s, a, b);
        }
        else if(action == "get"){
            ll player; std::cin >> player;
            ll res = get(L, s, player);
            std::cout << res << std::endl;
        }
    }

    return 0;
}

