        if(rv > after && rv == lv + 1 && f[node] >= val){return lv;}
        ll mid = (lv + rv) / 2;
        ll left = findMinIndex(val, after, 2*node + 1, lv, mid);
        if(left >= 0){return left;}
        ll right = findMinIndex(val, after, 2*node + 2, mid, rv);
        if(right >= 0){return right;}
        return -1;
    }
};


