        else if(lq <= lv && rv <= rq){return f[node];}
        else{
            ll mid = (lv + rv) / 2;
            std::vector<bool> leftVec = getCount(lq, rq, 2 * node + 1, lv, mid);
            std::vector<bool> rightVec = getCount(lq, rq, 2 * node + 2, mid, rv);
            return merge(leftVec,rightVec);
        }
    }
};


