int BFS (int s)
{
    int i,j,u,v;

    queue <int> Q;
    memset (visited,0,sizeof visited);
    Q.push(s);
    visited[s] = 1;

    while (!Q.empty())
    {
        u = Q.front();
        Q.pop();

        for (i=0; i<edges[u].size(); i++)
        {
            v = edges[u][i];

            if (!visited[v])
            {
                visited[v] = 1;
                Q.push(v);
            }
        }
    }

    return v;
}

