int bigmod (int base, int power, int mod)
{
    int p1,p2;

    if (power == 0)
        return 1;
    else if (power & 1)
    {
        p1 = base % mod;
        p2 = (bigmod (base, power-1, mod)) % mod;

        return (p1 * p2) % mod;
    }
    else if (power % 2 == 0)
    {
        p1 = (bigmod (base, power/2, mod)) % mod;

        return (p1 * p1) % mod;
    }
}

