int power (int b)
{
    int res = 1;

    while (b--)
        res *= 10;

    return res;
}

int remZero (int n)
{
    int res = 0;
    int r,k = -1;

    while (n)
    {
        r = n % 10;

        if (r != 0)
            res += (r * power (++k));

        n /= 10;
    }

    return res;
}

