// 489B - BerSU Ball
// http://codeforces.com/problemset/problem/489/B

#include <bits/stdc++.h>
#define FR(i, n) for (int i = 0; i < (n); ++i)
using namespace std;

typedef long long ll;
typedef pair<int, int> ii;
typedef vector<int> vi;

// https://en.wikipedia.org/wiki/Hopcroft–Karp_algorithm
// time complexity: O(E * sqrt(V))
class MaxMatching {
  public:
    static tuple<int, vi> max_matching(const vector<vi> &g) {
        int m = 0, n = g.size();

        for (auto &gg : g) {
            for (int u : gg) {
                m = max(m, u + 1);
            }
        }
        vi A(m, -1), D(n), matched(n);

        for (int i = 0, f = 0;; i += f, f = 0) {
            vi vis(n);
            bfs(g, matched, A, D);
            FR(u, n) if (!matched[u] && dfs(g, vis, matched, A, D, u)) f++;

            // final result condition
            if (!f) {
                return make_tuple(i, A);
            }
        }
    }

    static void bfs(const vector<vi> &g, vi &matched, vi &A, vi &D) {
        int n = g.size(), q = 0;
        fill(begin(D), end(D), -1);
        vi Q(n);
        FR(u, n) if (!matched[u]) Q[q++] = u, D[u] = 0;
        FR(i, q) {
            int u = Q[i];
            for (int v : g[u]) {
                int w = A[v];
                if (w >= 0 && D[w] < 0) D[w] = D[u] + 1, Q[q++] = w;
            }
        }
    }

    static bool dfs(const vector<vi> &g, vi &vis, vi &matched, vi &match, vi &D,
                    int u) {
        vis[u] = 1;
        for (int v : g[u]) {
            int w = match[v];
            if (w < 0 || (!vis[w] && D[w] == D[u] + 1 &&
                          dfs(g, vis, matched, match, D, w))) {
                match[v] = u;
                matched[u] = true;
                return true;
            }
        }
        return false;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    vi A(n);
    FR(i, n) cin >> A[i];

    int m;
    cin >> m;
    vi B(m);
    FR(i, m) cin >> B[i];

    vector<vi> g(101, vi());
    FR(i, n) {
        FR(j, m) {
            if (abs(A[i] - B[j]) < 2) {
                g[i].push_back(j + 100);
            }
        }
    }

    int t;
    tie(t, ignore) = MaxMatching::max_matching(g);
    cout << t << endl;
}

// 489C - Given Length and Sum of Digits...
// http://codeforces.com/problemset/problem/489/C
// Time Limit   : 1 seconds
// Memory Limit : 256 MB
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int m, s;
    cin >> m >> s;

    // Edge case, 0 <= s <= 900.
    if (s == 0) {
        cout << (m > 1 ? "-1 -1\n" : "0 0\n");
        return 0;
    }

    // Repeatedly subtract the largest possible single digit quantity from s,
    // resulting in { 9, 9, ... X } with 'X' being some value between 1 and 9.
    vector<int> A;
    while (s) A.push_back(min(9, s)), s -= min(9, s);
    vector<int> B(A);
    if (A.size() > m) {
        cout << "-1 -1\n";
        return 0;
    }
    // Min
    // Smallest possible will have a '1' in the most significant position, if
    // there is room left in our capacity 'm' digits, take 1 off the back,
    // append 0's, then re-add the 1.  This, reversed, is the smallest possible
    // number with 'm' digits, and digit-sum 's'
    while (A.size() < m) {
        A[A.size() - 1] -= 1;
        while (A.size() < m - 1) A.push_back(0);
        A.push_back(1);
    }
    for_each(rbegin(A), rend(A), [](auto a) { cout << a; }), cout << " ";

    // Max
    // Already in descending order, just need to append 0's if fewer than 'm'
    // elements in B
    while (B.size() < m) B.push_back(0);
    for_each(begin(B), end(B), [](auto b) { cout << b; }), cout << "\n";
}

