// Basic point structure
typedef double T;
struct pt {
  T x, y;
  pt operator+(pt p) { return {x + p.x, y + p.y}; }
  pt operator-(pt p) { return {x - p.x, y - p.y}; }
  pt operator*(T d) { return {x * d, y * d}; }
  bool operator==(pt a) { return (a.x == x && a.y == y); }
  T sq(pt p) { return p.x * p.x + p.y * p.y; }
  T dist(pt p) { return ((p.x - x) * (p.x - x) + (p.y - y) * (p.y - y)); }
};

