// Euclid's algorithm for Greatest Common Divisor
// https://en.wikipedia.org/wiki/Euclidean_algorithm
// Complexity: O(log n), where n = min(a, b)
int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

// Least Common Multiple
int lcm(int a, int b) {
    return a * (b / gcd(a, b));
}

