void solve()
{
    int n, k; cin >> n >> k;
    string s; cin >> s;
    map <char , ll> mp;
    
    for(ll i = 0; i<n; i++){
        mp[s[i]]++;
    }

    ll pair = 0, unpair = 0;
    for(auto it : mp){
        ll x = it.second;

        pair += (x/2);

        unpair += (x%2);
    }

