void solve()
{
    ll n;
    cin >> n;
    ll array[n];
    map <ll, ll> mp;
    for(int i = 0 ; i< n; i++){
        cin >> array[i];
        mp[array[i] - (i+1)]++;
    }
    ll ans = 0;
    for(auto x : mp){
        ans += (x.second * (x.second -1))/ 2;

    }
    cout << ans << endl;

}

